// Gathers the group's channels of one mixed Q/K/V row and convolves them in
// place. See Note [Rolling GatedDeltaNet execution].
template <gdn_activation_row<full_convolution_channels> mixed_qkv_row>
void convolve_token(mixed_qkv_row const& mixed_qkv) noexcept {
  working_set& working = *working_;
  for (size_t chunk = 0; chunk < group_convolution_chunks; ++chunk)
    working.convolution_qkv.store_chunk(
        chunk, mixed_qkv.chunk(working.source_chunks[chunk]));
  gdn_conv1d_silu(working.convolution_qkv,
      gdn_conv1d_history<full_convolution_channels>(working.convolution_history,
          full_convolution_channels * gdn_conv1d_history_width),
      working.convolution_qkv, working.operation->convolution_weights,
      working.source_chunks);
}
